module tb;
    reg  [7:0] a;
    reg  [7:0] b;
    wire [7:0] s;
    wire       overflow;

    TopModule dut (
        .a(a),
        .b(b),
        .s(s),
        .overflow(overflow)
    );

    integer errors = 0;
    reg [8:0] expected_sum;
    reg       expected_ovf;

    // Task to apply vectors and check against golden model
    task check(input [7:0] test_a, input [7:0] test_b);
        begin
            a = test_a;
            b = test_b;
            #5; // Allow propagation

            // Golden model calculation using 9-bit signed addition
            expected_sum = $signed(test_a) + $signed(test_b);
            expected_ovf = (expected_sum[8] !== expected_sum[7]);

            if (s !== expected_sum[7:0]) begin
                $display("Mismatch: a=%d, b=%d | Expected s=%d, Got s=%d", 
                         $signed(test_a), $signed(test_b), expected_sum[7:0], s);
                errors = errors + 1;
            end

            if (overflow !== expected_ovf) begin
                $display("Overflow Mismatch: a=%d, b=%d | Expected ovf=%b, Got ovf=%b", 
                         $signed(test_a), $signed(test_b), expected_ovf, overflow);
                errors = errors + 1;
            end
        end
    endtask

    initial begin
        // Test Case 1: Zero + Zero
        check(8'sd0, 8'sd0);

        // Test Case 2: Positive + Positive (No overflow)
        check(8'sd50, 8'sd20);

        // Test Case 3: Positive + Positive (Overflow boundary: 127 + 1)
        check(8'sd127, 8'sd1);

        // Test Case 4: Negative + Negative (No overflow: -50 + -20)
        check(-8'sd50, -8'sd20);

        // Test Case 5: Negative + Negative (Overflow boundary: -128 + -1)
        check(-8'sd128, -8'sd1);

        // Test Case 6: Positive + Negative (No overflow possible)
        check(8'sd50, -8'sd20);
        check(-8'sd50, 8'sd20);

        // Test Case 7: Maximum positive sum without overflow (127 + 0)
        check(8'sd127, 8'sd0);

        // Test Case 8: Maximum negative sum without overflow (-128 + 0)
        check(-8'sd128, 8'sd0);

        // Test Case 9: Cancellation leading to zero
        check(8'sd100, -8'sd100);

        // Test Case 10: Random / Corner vectors
        check(8'h7F, 8'h7F); // 127 + 127 (Overflow)
        check(8'h80, 8'h80); // -128 + -128 (Overflow)
        check(8'h55, 8'h2A); 
        check(8'hAA, 8'h55);

        #10;
        if (errors === 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

endmodule
